    "🚐 *La vostra piazzola:* una volta dentro scegliete voi un posto. Fateci sapere su WhatsApp su quale piazzola siete. Il resto lo scoprirete da soli nella finca.",
    "🌐 *Wifi:* {wifi_netwerk} / {wifi_wachtwoord}",
    "🏕️ *Il terreno:* il vostro posto è il campo dei camper e il campo in basso, con il parco giochi. La terrazza, la piscina e il bar sono anche per voi; i bambini sotto i 12 anni ci vanno solo insieme a un genitore.",
    "🍽️ *Mangiare e bere:* il vostro cibo e le vostre bevande li gustate al camper. In terrazza e al bar li prendete dall'honesty bar e li segnate voi stessi sulla vostra pagina ospiti.",
    "🍺 *Bar:* aperto fino alle 23:30, dalle 10:00 per tutti; prima solo se avete ordinato da noi la colazione o i panini.",
    "",
