    "Qui sotto trovate tutte le informazioni pratiche sulla finca. Leggetele con calma 👇", "",
    STREEP, "",
    "🐕 ANIMALI", "",
    "Gli animali sono i benvenuti, ma sempre al guinzaglio.",
    "• Non al bar e non nelle strutture comuni.",
    "• I bisogni si fanno fuori dal cancello.", "",
    STREEP, "",
    "👧 BAMBINI", "",
    "I bambini sono i benvenuti. In basso, vicino al campo dei camper, c'è il parco giochi, dove possono giocare in libertà.",
    "• I bambini sotto i 12 anni non stanno mai in terrazza, in piscina o al bar senza un genitore.",
    "• Dopo aver giocato si riordina insieme 🙏", "",
    STREEP, "",
    "🌞 DOVE POTETE ANDARE", "",
    "Il vostro posto è il campo dei camper e il campo in basso. Inoltre siete i benvenuti in terrazza, in piscina e al bar; i bambini sotto i 12 anni sempre insieme a un genitore.", "",
    "• I nostri ospiti delle camere arrivano in aereo e non hanno nulla con sé. Per questo i lettini e i mobili della terrazza sono per loro. Portate la vostra sedia o il vostro asciugamano, così c'è posto per tutti.",
    "• Niente fumo in terrazza, e niente vetro in piscina.",
    "• Niente scarpe sui lettini; i bambini saltano sul trampolino, non sui lettini.",
    "• Lasciate la terrazza in ordine.", "",
