    "Chaque chambre a aussi une climatisation qui rafraîchit et chauffe. Pour économiser l'énergie, elle s'éteint d'elle-même quelques fois par jour pendant un court moment, 30 minutes au maximum. Il suffit ensuite de la rallumer avec la télécommande.", "",
