    "Cada quarto tem também ar condicionado que arrefece e aquece. Para poupar energia, o aparelho desliga-se sozinho algumas vezes por dia durante pouco tempo, no máximo cerca de 30 minutos. Depois basta voltar a ligá-lo com o comando.", "",
    "Continua a não funcionar bem? Digam-nos.", "",
