    "🌿 EXTRAS", "",
    "Querem tornar a estadia ainda mais completa? Peçam através da vossa página de hóspedes (Extras) e propomos-vos rapidamente um dia e uma hora.",
    "• 💆 Massagem no local: 60 € por pessoa, 60 minutos",
