    "• Não no bar nem junto às instalações comuns.",
    "• Os passeios para as necessidades fazem-se fora do portão.", "",
    STREEP, "",
    "👧 CRIANÇAS", "",
    "As crianças são muito bem-vindas. Em baixo, junto ao campo das autocaravanas, está o parque infantil, onde podem brincar à vontade.",
    "• As crianças com menos de 12 anos nunca estão no terraço, na piscina ou no bar sem um dos pais.",
    "• Depois de brincar, arrumamos todos juntos 🙏", "",
    STREEP, "",
    "🌞 ONDE PODEM IR", "",
    "O vosso lugar é o campo das autocaravanas e o campo de baixo. Além disso são bem-vindos no terraço, na piscina e no bar; as crianças com menos de 12 anos sempre acompanhadas de um dos pais.", "",
    "• Os nossos hóspedes dos quartos vêm de avião e não trazem nada. Por isso as espreguiçadeiras e os móveis do terraço são para eles. Tragam a vossa própria cadeira ou toalha, assim há lugar para todos.",
    "• Sem fumo no terraço, e nada de vidro na piscina.",
    "• Sem sapatos nas espreguiçadeiras; as crianças saltam no trampolim, não nas espreguiçadeiras.",
    "• Deixem o terraço arrumado.", "",
    STREEP, "",
    "🍽️ COMER E BEBER", "",
    "• A vossa própria comida e bebida: à vontade na autocaravana, no vosso lugar.",
    "• No terraço e no bar tudo vem do honesty bar: tirem o que quiserem e apontem-no vocês mesmos na vossa página de hóspedes.",
    "• Na piscina nada de comida, bebida ou vidro, para que se mantenha segura e limpa.", "",
    STREEP, "",
