    STREEP, "",
    "🏊 PISCINA", "",
    "Nadar é por vossa conta e risco. As crianças com menos de 12 anos sempre acompanhadas de um dos pais.",
    "As regras da piscina estão na placa junto à piscina.", "",
    STREEP, "",
    "🌙 SOSSEGO", "",
    "A partir das 00:00 faz-se silêncio lá fora, por respeito pelos vizinhos, pelo ambiente e pelos outros hóspedes.", "",
    STREEP, "",
