    "• Huonevieraamme tulevat lentäen eikä heillä ole mitään mukanaan. Siksi aurinkotuolit ja terassin kalusteet ovat heitä varten. Ottakaa oma tuoli tai pyyhe mukaan, niin kaikille riittää tilaa.",
