  kamerCheckin: c => [
    `Hei${c.naam ? " " + c.naam : ""} 😊`, "",
    `${c.vandaag ? "I dag" : "I morgen"} er dagen kommet, vi gleder oss til å ønske dere velkommen på Finca KaYu! ☀️`, "",
    "⏰ *Innsjekking* fra kl. 15:00",
    `🛏️ *${c.aantalKamers > 1 ? "Rommene deres:" : "Rommet deres:"}* ${c.kamer}`, "",
    ...(c.groep ? [] : ["🔑 Noen ganger hender det at vi ikke er her akkurat når dere kommer. Ingen fare: etter innsjekkingen på nett nedenfor finner dere alt på siden deres for å komme inn selv, også portkoden. Vi kommer innom senere på dagen og hilser på.", ""]),
    "📝 *Bare én ting på forhånd: sjekk inn på nett*",
    "Da trenger dere ikke ordne noe mer når dere kommer. I Spania registrerer vi alle gjester, også barna. Det tar bare noen minutter:",
    `👉 ${c.link}`, "",
    "Ha passene eller ID-kortene klare. Hovedgjesten signerer med fingeren.", "",
    "Etter innsjekkingen leser dere husreglene våre og trykker nederst for å godta dem. Deretter åpnes gjestesiden deres med en gang, med veibeskrivelse, portkoden, wifi, frokost og tipsene våre. Lenken virker under hele oppholdet.", "",
    /* 16-10-2026 a (Bart): de link delen met kamergenoten; 17-10-2026 a (Bart: "Akkoord"): bij meer kamers op één naam: iedereen invullen, daarna een eigen link per kamer */
    ...(c.groep ? [] : [c.aantalKamers > 1 ? `Dere har booket ${c.aantalKamers} rom (rom ${c.kamer}). Fyll ut alle ved innsjekkingen, også dem som sover på de andre rommene. Etterpå får dere en egen lenke for hvert rom som dere kan sende videre.` : "Del lenken med alle som sover på rommet med dere. Da kan alle bestille frokost selv og lese alt om fincaen.", ""]),
    "🕒 Kan dere også gi oss beskjed om omtrent når dere regner med å komme?", "",
    c.totDag, "", "Beste hilsen,", "Bart & Loes", "Finca KaYu ☀️"
  ],
