    "Håll utkik efter våra skyltar med logotypen på den sista biten, de leder er till grinden.",
    "🚪 *Grinden:* ring eller skicka ett WhatsApp-meddelande till +34 722 162 962 när ni står vid grinden, så öppnar vi. Svarar vi inte? Då kommer ni in själva med koden {poortcode}.",
    "Köra ut: tryck på knappen, sedan har ni ungefär 60 sekunder.",
    "🚐 *Er plats:* väl inne väljer ni själva en plats. Meddela oss via WhatsApp vilken plats ni står på. Resten upptäcker ni själva på området.",
    "🌐 *Wifi:* {wifi_netwerk} / {wifi_wachtwoord}",
    "🏕️ *Området:* er plats är husbilsfältet och det nedre fältet, med lekplatsen. Terrassen, poolen och baren är också till för er; barn under 12 år kommer dit bara tillsammans med en förälder.",
    "🍽️ *Mat och dryck:* egen mat och dryck njuter ni av vid husbilen. På terrassen och i baren tar ni det från honesty bar och registrerar det själva på er gästsida.",
