    "Här nedanför hittar ni all praktisk information om fincan. Läs den noga 👇", "",
    STREEP, "",
    "🐕 HUSDJUR", "",
    "Husdjur är välkomna, men alltid kopplade.",
    "• Inte i baren och inte vid anläggningarna.",
    "• Rasta dem utanför grinden.", "",
    STREEP, "",
    "👧 BARN", "",
    "Barn är varmt välkomna. Nere vid husbilsfältet finns lekplatsen, där kan de leka så mycket de vill.",
    "• Barn under 12 år är aldrig på terrassen, vid poolen eller i baren utan en förälder.",
    "• Plocka undan tillsammans efter leken 🙏", "",
    STREEP, "",
    "🌞 VAR NI FÅR VARA", "",
    "Er plats är husbilsfältet och det nedre fältet. Dessutom är ni välkomna på terrassen, vid poolen och i baren; barn under 12 år alltid tillsammans med en förälder.", "",
    "• Våra rumsgäster kommer med flyg och har ingenting med sig. Därför är solsängarna och terrassmöblerna till för dem. Ta med egen stol eller handduk, så finns det plats för alla.",
    "• Rökfritt på terrassen, och inget glas vid poolen.",
    "• Inga skor på solsängarna; barn hoppar på studsmattan, inte på solsängarna.",
    "• Lämna terrassen i ordning.", "",
