    "• Vid poolen ingen mat, dryck eller glas, så förblir det säkert och rent där.", "",
    STREEP, "",
    "💵 HONESTY BAR", "",
    "Ta det ni vill ha och registrera det på er gästsida; ni betalar vid utcheckningen, helst kontant.",
